from pathlib import Path
import json,re

root=Path('.')
app_path=root/'app.jsx'
s=app_path.read_text(encoding='utf-8')

# Generated by workflow from the game's own zh-CN resources.
name_map=json.loads(Path('/tmp/switch_names.json').read_text(encoding='utf-8'))
(root/'switch-names-v47.js').write_text(
    '/* Official Stardew Valley zh-CN display names, generated from pinned unpacked game localization. */\n'
    'window.SDVSwitchNamesV47='+json.dumps(name_map,ensure_ascii=False,separators=(',',':'))+';\n',
    encoding='utf-8'
)

helper='''\nconst SWITCH_ITEM_NAMES_V47 = window.SDVSwitchNamesV47 || {};\nfunction switchItemNameV47(fallback,file){\n  const rawFile=String(file||\"\");\n  const baseFile=rawFile.replace(/@\\d+$/,'');\n  return SWITCH_ITEM_NAMES_V47[rawFile] || SWITCH_ITEM_NAMES_V47[baseFile] || SWITCH_ITEM_NAMES_V47[String(fallback||\"\")] || fallback;\n}\nfunction switchItemTextV47(raw){\n  const text=String(raw||\"\");\n  if(!text)return text;\n  const q=text.match(/^(.*?)(\\s*[×x]\\s*\\d+.*)$/);\n  const left=(q?q[1]:text).trim();\n  const suffix=q?q[2]:\"\";\n  const quality=left.match(/^(金星|銀星|银星|銥星|铱星)(.*)$/);\n  const prefix=quality?quality[1]:\"\";\n  const base=(quality?quality[2]:left).trim();\n  let file=\"\";\n  try{ file=itemFileZhV26(base)||\"\"; }catch(e){}\n  return `${prefix}${switchItemNameV47(base,file)}${suffix}`;\n}\nfunction switchLookupTextV47(raw){\n  const text=String(raw||\"\");\n  if(!text)return text;\n  if(text.startsWith(\"製作材料：\"))return \"製作材料：\"+switchItemNameV47(text.slice(5).trim(),text.slice(5).trim());\n  if(text.startsWith(\"制作材料：\"))return \"制作材料：\"+switchItemNameV47(text.slice(5).trim(),text.slice(5).trim());\n  return text;\n}\nlet switchNamesAppliedV47=false;\nfunction applySwitchNamesV47(){\n  if(switchNamesAppliedV47)return;\n  switchNamesAppliedV47=true;\n  const renamePairRows=rows=>(rows||[]).forEach(row=>{if(Array.isArray(row)&&row.length>1)row[1]=switchItemNameV47(row[1],row[0]);});\n  try{ renamePairRows(SHIPPING_ITEMS_V30); }catch(e){}\n  try{ renamePairRows(BOOTS_V30); }catch(e){}\n  try{ renamePairRows(HATS_V30); renamePairRows(SHIRTS_V30); renamePairRows(PANTS_V30); }catch(e){}\n  try{\n    [ [COLLECTIONS.fish,FISH_ICON_FILES],[COLLECTIONS.artifact,ARTIFACT_ICON_FILES],[COLLECTIONS.mineral,MINERAL_ICON_FILES] ].forEach(([c,files])=>c.items.forEach((name,i)=>{c.items[i]=switchItemNameV47(name,files[i]);}));\n  }catch(e){}\n  try{ (MINE_BANDS_V28||[]).forEach(g=>(g.items||[]).forEach(row=>{row[1]=switchItemNameV47(row[1],row[0]);})); }catch(e){}\n  try{ (COOKING_DISHES_V3||[]).forEach(row=>{row[1]=switchItemNameV47(row[1],row[2]);}); }catch(e){}\n  try{ (COOKING_PREP_GROUPS_V3||[]).forEach(g=>(g.items||[]).forEach(row=>{row[1]=switchItemNameV47(row[1],row[2]);})); }catch(e){}\n  try{ Object.values(BUNDLE_REWARDS_V28||{}).forEach(row=>{if(Array.isArray(row))row[1]=switchItemNameV47(row[1],row[0]);}); }catch(e){}\n  try{ BUNDLE_ROOMS.forEach(room=>room.bundles.forEach(bundle=>{bundle.items=bundle.items.map(switchItemTextV47);})); }catch(e){}\n  try{ Object.keys(REMIX_EXTRA_ITEMS_V28||{}).forEach(k=>{REMIX_EXTRA_ITEMS_V28[k]=(REMIX_EXTRA_ITEMS_V28[k]||[]).map(switchItemTextV47);}); }catch(e){}\n  try{ Object.values(FESTIVAL_GUIDE_V26||{}).forEach(v=>(v.items||[]).forEach(row=>{row[1]=switchItemNameV47(row[1],row[0]);})); }catch(e){}\n  try{ (SPECIAL_ITEMS_V2||[]).forEach(it=>{it.name=switchItemNameV47(it.name,it.file);}); }catch(e){}\n  try{ (BOOK_POWERS_V2||[]).forEach(it=>{it.name=switchItemNameV47(it.name,it.file);}); }catch(e){}\n  try{\n    const db=window.SDVWardrobeV34||{};\n    ['hats','shirts','pants'].forEach(k=>(db[k]||[]).forEach(it=>{it.name=switchItemNameV47(it.name,it.icon||it.key); if(it.recipe)it.recipe=it.recipe.split('＋').map(part=>{const m=part.match(/^(布料|Cloth)(.*)$/);if(m)return '布料'+m[2];return switchItemTextV47(part);}).join('＋');}));\n  }catch(e){}\n}\n'''
needle='const SEASON_ICON = { 春: "🌸", 夏: "☀️", 秋: "🍁", 冬: "❄️" };\n'
if helper.strip() not in s:
    if needle not in s: raise SystemExit('SEASON_ICON insertion point not found')
    s=s.replace(needle,needle+helper,1)

# Apply official names before any render-time datasets are consumed.
if 'function StardewTracker() {' not in s: raise SystemExit('StardewTracker not found')
s=s.replace('function StardewTracker() {','function StardewTracker() {\n  applySwitchNamesV47();',1)

# Lookup: official Switch display name wins, while old zh/wiki and English stay searchable aliases.
old='(window.SDVLookupV46?.items||[]).forEach(row=>{const it=ensure(row.zh||row.name,row.file||row.name,row.kind||"game");if(!it)return;it.aliases.add(row.name);(row.aliases||[]).forEach(x=>it.aliases.add(x));(row.sources||[]).forEach(x=>it.sources.add(x));(row.uses||[]).forEach(x=>it.uses.add(x));if(row.recommend)it.recommend=row.recommend;});'
new='(window.SDVLookupV46?.items||[]).forEach(row=>{const display=switchItemNameV47(row.zh||row.name,row.file||row.name);const it=ensure(display,row.file||row.name,row.kind||"game");if(!it)return;it.aliases.add(row.name);if(row.zh)it.aliases.add(row.zh);(row.aliases||[]).forEach(x=>it.aliases.add(x));(row.sources||[]).forEach(x=>it.sources.add(x));(row.uses||[]).forEach(x=>it.uses.add(switchLookupTextV47(x)));});'
if old not in s: raise SystemExit('lookup ingestion target not found')
s=s.replace(old,new,1)

# Wardrobe cards should always display official game names from the English item key/icon.
old='const wrap=arr=>(arr||[]).map(x=>[x.key,x.name,x.sourceZh||x.source,x.dyeable,x]);'
new='const wrap=arr=>(arr||[]).map(x=>[x.key,switchItemNameV47(x.name,x.icon||x.key),x.sourceZh||x.source,x.dyeable,x]);'
if old not in s: raise SystemExit('wardrobe wrap target not found')
s=s.replace(old,new,1)

# Remove all keep/sell advice from the lookup card; uses and acquisition source are the point.
s=re.sub(r'\n\s*const mustKeepV46=.*?;\n\s*const recommendActionV46=.*?;','',s,count=1)
# remove the recommendation column from selected card and make source full-width
pattern=r'''<div style=\{\{display:"grid",gridTemplateColumns:"minmax\(0,1fr\) 58px",gap:8,alignItems:"stretch",marginTop:9,paddingTop:7,borderTop:`1px dashed \$\{C\.line\}`\}\}>\s*<div style=\{\{minWidth:0\}\}><span style=\{\{fontSize:7\.4,color:C\.muted,fontWeight:900\}\}>來源</span><div style=\{\{fontSize:8\.5,color:C\.ink,lineHeight:1\.35,marginTop:2\}\}>\{sourceTextV45\}</div></div>\s*<div.*?>.*?recommendActionV46.*?</div>\s*</div>'''
replacement='''<div style={{marginTop:9,paddingTop:7,borderTop:`1px dashed ${C.line}`}}><span style={{fontSize:8,color:C.muted,fontWeight:900}}>來源</span><div style={{fontSize:9.6,color:C.ink,lineHeight:1.45,marginTop:3}}>{sourceTextV45}</div></div>'''
s,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'recommendation UI target count={n}')

# Remove recommendation data plumbing that is no longer used.
s=s.replace('recommend:"",','')
s=s.replace('if(row.recommend)it.recommend=row.recommend;','')

# Data page hierarchy: top-level Skill bucket -> Character; child Skill -> Level.
lines=s.splitlines()
data_hits=skill_hits=0
for i,line in enumerate(lines):
    if 'dataSection' in line and '技能' in line:
        lines[i]=line.replace('技能','角色',1); data_hits+=1
    if 'skillSection' in lines[i] and '技能' in lines[i]:
        lines[i]=lines[i].replace('技能','等級',1); skill_hits+=1
s='\n'.join(lines)+'\n'
if data_hits<1: raise SystemExit('dataSection 技能 label not found')
if skill_hits<1: raise SystemExit('skillSection 技能 label not found')

# Item list sorting follows the official Chinese display strings.
s=s.replace('localeCompare(b.name,"zh-Hant")','localeCompare(b.name,"zh-CN")')

app_path.write_text(s,encoding='utf-8')

# Load official-name mapping before all feature data and bump browser cache.
idx=Path('index.html')
i=idx.read_text(encoding='utf-8')
i=re.sub(r'\?v=46', '?v=47', i)
if 'switch-names-v47.js' not in i:
    i=i.replace('<script src="./cloud.js?v=47"></script>','<script src="./cloud.js?v=47"></script>\n  <script src="./switch-names-v47.js?v=47"></script>',1)
i=i.replace('deploy-v46','deploy-v47')
idx.write_text(i,encoding='utf-8')

sw=Path('sw.js')
w=sw.read_text(encoding='utf-8')
w=w.replace('stardew-tracker-v46','stardew-tracker-v47')
if "'./switch-names-v47.js'" not in w:
    # append beside lookup data in the precache list
    w=w.replace("'./lookup-data-v46.js'", "'./lookup-data-v46.js','./switch-names-v47.js'")
sw.write_text(w,encoding='utf-8')

print('official name map entries:',len(name_map),'data label hits:',data_hits,'skill label hits:',skill_hits)
